BEGIN;
CREATE TABLE tender_fms_intakes(id uuid PRIMARY KEY,title varchar(255) NOT NULL,owner_id uuid NOT NULL REFERENCES users(id),initial_sha256 varchar(64) NOT NULL,version integer NOT NULL DEFAULT 1,is_active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),created_by_id uuid REFERENCES users(id),updated_by_id uuid REFERENCES users(id),UNIQUE(owner_id,initial_sha256));
CREATE TABLE document_readings(id uuid PRIMARY KEY,module varchar(64) NOT NULL,entity_id uuid NOT NULL,filename varchar(200) NOT NULL,format varchar(8) NOT NULL CHECK(format IN ('pdf','xlsx','xls','docx','doc')),size_bytes bigint NOT NULL CHECK(size_bytes BETWEEN 1 AND 33554432),sha256 varchar(64) NOT NULL,original bytea NOT NULL,status varchar(16) NOT NULL DEFAULT 'queued' CHECK(status IN ('queued','processing','ready','failed')),version integer NOT NULL DEFAULT 1,attempts integer NOT NULL DEFAULT 0 CHECK(attempts BETWEEN 0 AND 3),claim_id uuid,lease_until timestamptz,error_message varchar(300) NOT NULL DEFAULT '',segment_count integer NOT NULL DEFAULT 0,warnings jsonb NOT NULL DEFAULT '[]',is_active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),created_by_id uuid REFERENCES users(id),updated_by_id uuid REFERENCES users(id),UNIQUE(module,entity_id,sha256));
CREATE INDEX document_readings_queue ON document_readings(status,created_at) WHERE status IN ('queued','processing');
CREATE INDEX document_readings_scope ON document_readings(module,entity_id);
CREATE TABLE document_reading_results(document_id uuid PRIMARY KEY REFERENCES document_readings(id),result bytea NOT NULL,result_sha256 varchar(64) NOT NULL,reader_version varchar(80) NOT NULL,is_active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),created_by_id uuid REFERENCES users(id),updated_by_id uuid REFERENCES users(id));
CREATE TABLE document_reading_events(id uuid PRIMARY KEY,document_id uuid NOT NULL REFERENCES document_readings(id),action varchar(40) NOT NULL,version integer NOT NULL,actor_id uuid REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE TABLE tender_fms_events(id uuid PRIMARY KEY,intake_id uuid NOT NULL REFERENCES tender_fms_intakes(id),action varchar(40) NOT NULL,document_id uuid NOT NULL REFERENCES document_readings(id),actor_id uuid REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE FUNCTION protect_reading_evidence() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Document originals, results and history are immutable'; END $$;
CREATE TRIGGER immutable_reading_result BEFORE UPDATE OR DELETE ON document_reading_results FOR EACH ROW EXECUTE FUNCTION protect_reading_evidence();
CREATE TRIGGER immutable_reading_event BEFORE UPDATE OR DELETE ON document_reading_events FOR EACH ROW EXECUTE FUNCTION protect_reading_evidence();
CREATE TRIGGER immutable_tender_intake_event BEFORE UPDATE OR DELETE ON tender_fms_events FOR EACH ROW EXECUTE FUNCTION protect_reading_evidence();
CREATE FUNCTION protect_reading_source() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Document originals cannot be deleted'; END IF;
IF ROW(NEW.module,NEW.entity_id,NEW.filename,NEW.format,NEW.size_bytes,NEW.sha256,NEW.original,NEW.created_at,NEW.created_by_id) IS DISTINCT FROM ROW(OLD.module,OLD.entity_id,OLD.filename,OLD.format,OLD.size_bytes,OLD.sha256,OLD.original,OLD.created_at,OLD.created_by_id) THEN RAISE EXCEPTION 'Document original is immutable'; END IF;
IF OLD.status='ready' THEN RAISE EXCEPTION 'Completed reading is immutable'; END IF; RETURN NEW; END $$;
CREATE TRIGGER immutable_reading_source BEFORE UPDATE OR DELETE ON document_readings FOR EACH ROW EXECUTE FUNCTION protect_reading_source();
COMMIT;
